import React from "react";
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Textarea.stories";
import Textarea from ".";

const { Basic } = composeStories(stories) as any;

describe("Textarea component", () => {
  beforeAll(() => {
    // FIXME remove this workaround
    // @see https://github.com/nickcolley/jest-axe/issues/147
    const { getComputedStyle } = window;
    window.getComputedStyle = (elt) => getComputedStyle(elt);
  });

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(
      <Textarea rows={4} placeholder="Text" data-testid="textarea" />
    );
    expect(screen.queryByRole("textbox")).toHaveAttribute("data-testid", "textarea");
  });

  it("dispatch event and value", async () => {
    const onChange = jest.fn();
    render(<Textarea onChange={onChange} />);
    const input = screen.getByRole("textbox");
    await userEvent.type(input, "test");
    expect(input).toHaveValue("test");
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onChange).toHaveBeenLastCalledWith(expect.anything(), "test");
  });

  it("allow forwardRef", () => {
    const TextareaWithRef = () => {
      const textareaRef = React.useRef<HTMLTextAreaElement>(null);
      React.useEffect(() => {
        textareaRef.current && textareaRef.current.focus();
      }, []);
      return <Textarea ref={textareaRef} />;
    };

    render(<TextareaWithRef />);
    expect(screen.getByRole("textbox")).toHaveFocus();
  });
});
